"""
export_service - Datenbankabfragen ausfuehren und optional exportieren.
"""

import logging
import os

import mariadb
import pandas as pd

from ..constants import DATABASE
from ..utils.excel_utils import export_dataframe_to_excel
from .client import connect_to_db

logger = logging.getLogger(__name__)


def _build_export_path(path: str | None, output: str | None, suffix: str) -> str:
    """Erstellt einen Exportpfad und validiert die notwendigen Angaben."""
    if not path:
        raise ValueError("Pfad muss fuer einen Export angegeben werden.")
    if not output:
        raise ValueError("output muss fuer einen Export angegeben werden.")
    return os.path.join(path, f"{output}{suffix}")


def datenbankabfrage_mit_export(
    sql_abfrage: str,
    output: str | None = "ohne",
    pfad: str | None = None,
    typ: str | None = None,
    split_in_chunks: str | None = None,
    database: str = DATABASE,
) -> pd.DataFrame:
    """Fuehrt eine SQL-Abfrage aus und exportiert die Ergebnisse optional in eine datei.

    Args:
        sql_abfrage: SQL-Abfrage, die ausgefuehrt werden soll.
        output: Dateiname ohne Erweiterung fuer Exporte.
        pfad: Zielverzeichnis fuer Exporte.
        typ: Exporttyp, z. B. ``"Excel"``, ``"CSV"`` oder ``"ohne"``.
        split_in_chunks: ``"Ja"`` teilt CSV-Exporte in mehrere Dateien.
        database: Name der Datenbank.

    Returns:
        DataFrame mit dem Abfrageergebnis.
    """
    connection = None
    cursor = None
    try:
        connection = connect_to_db(database)

        cursor = connection.cursor(dictionary=True)
        cursor.execute(sql_abfrage)
        result = cursor.fetchall()
        df = pd.DataFrame(result)

        if typ:
            export_type = typ.lower()
            if export_type == "excel":
                output_file = str(
                    export_dataframe_to_excel(
                        df,
                        _build_export_path(pfad, output, ".xlsx"),
                    )
                )
                logger.info("Die Daten wurden erfolgreich in die datei '%s' exportiert.", output_file)
            elif export_type == "csv":
                if split_in_chunks == "Ja":
                    chunk_size = 2000
                    num_chunks = (len(df) // chunk_size) + 1
                    for index in range(num_chunks):
                        chunk = df.iloc[index * chunk_size : (index + 1) * chunk_size]
                        output_file_chunk = _build_export_path(pfad, f"{output}_part{index + 1}", ".csv")
                        chunk.to_csv(output_file_chunk, index=False, encoding="utf-8-sig")
                        logger.info("Die Daten wurden erfolgreich in die datei '%s' exportiert.", output_file_chunk)
                else:
                    output_file = _build_export_path(pfad, output, ".csv")
                    df.to_csv(output_file, index=False, encoding="utf-8-sig")
                    logger.info("Die Daten wurden erfolgreich in die datei '%s' exportiert.", output_file)
            elif export_type == "ohne":
                logger.info("Kein Export gewuenscht. Der DataFrame wird angezeigt:")
                logger.debug("DataFrame:\n%s", df)
            else:
                logger.warning("Ungueltiger Typ angegeben. Der DataFrame wird angezeigt:")
                logger.debug("DataFrame:\n%s", df)
        else:
            logger.warning("Kein Typ angegeben. Der DataFrame wird angezeigt:")
            logger.debug("DataFrame:\n%s", df)
        return df
    except mariadb.Error as exc:
        logger.error("Fehler, %s", exc, exc_info=True)
        raise
    finally:
        if cursor:
            cursor.close()
        if connection:
            connection.close()
